    use aap:caps/types@0.1.0.{subscription-list, feed-batch};
    import aap:caps/http-client@0.1.0;

    export run: func(subscriptions: subscription-list) -> feed-batch;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client::fetch;

const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the host of an http(s) URL, or `None` if the URL has no
/// recognisable host (including any userinfo, which is refused outright).
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(|c| c == '/' || c == '?' || c == '#').next()?;
    if authority.contains('@') {
        return None;
    }
    let host = authority.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            let allowed = host_of(&url).is_some_and(|h| ALLOWED_HOSTS.contains(&h));
            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            match fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch { documents, failures }
    }
}

export!(Node);
